package io.aetheris.orchestrator.trading;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="aetheris_stage9_advanced_backtests") public class AdvancedBacktestResultEntity {@Id private UUID id;@Column(nullable=false,length=40) private String symbol;private int bars;private int trades;private double netReturnPct;private double winRatePct;private double maxDrawdownPct;private double totalCosts;private int walkForwardWindows;@Column(nullable=false,length=4000) private String windowSummary;@Column(nullable=false,length=1000) private String regimeSummary;@Column(nullable=false) private Instant createdAt;protected AdvancedBacktestResultEntity(){}public AdvancedBacktestResultEntity(UUID id,String symbol,int bars,int trades,double net,double win,double dd,double costs,int windows,String windowSummary,String regimeSummary){this.id=id;this.symbol=symbol;this.bars=bars;this.trades=trades;this.netReturnPct=net;this.winRatePct=win;this.maxDrawdownPct=dd;this.totalCosts=costs;this.walkForwardWindows=windows;this.windowSummary=windowSummary;this.regimeSummary=regimeSummary;this.createdAt=Instant.now();}public UUID getId(){return id;}public String getSymbol(){return symbol;}public int getBars(){return bars;}public int getTrades(){return trades;}public double getNetReturnPct(){return netReturnPct;}public double getWinRatePct(){return winRatePct;}public double getMaxDrawdownPct(){return maxDrawdownPct;}public double getTotalCosts(){return totalCosts;}public int getWalkForwardWindows(){return walkForwardWindows;}public String getWindowSummary(){return windowSummary;}public String getRegimeSummary(){return regimeSummary;}public Instant getCreatedAt(){return createdAt;}}
